    def stirling_second_kind(n, k, p):
        dp = [[0] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 1
        for i in range(1, n + 1):
            for j in range(1, k + 1):
                dp[i][j] = (dp[i - 1][j - 1] + j * dp[i - 1][j]) % p
        return dp[n][k]

    def bell_number(n, k, p):
        bell = [0] * (n + 1)
        bell[0] = 1
